def is_square_attacked(board, square, attacker_color):
    rank, file = square_to_coords(square)

    # Check pawn attacks
    pawn_dir = 1 if attacker_color == 'w' else -1
    for df in [-1, 1]:
        pr, pf = rank + pawn_dir, file + df
        if 0 <= pr < 8 and 0 <= pf < 8:
            if get_piece_at(board, pr, pf) == attacker_color + 'P':
                return True

    # Check knight attacks
    for dr, df in [(-2,-1), (-2,1), (-1,-2), (-1,2), (1,-2), (1,2), (2,-1), (2,1)]:
