        if 0 <= nr < 8 and 0 <= nf < 8:
            if get_piece_at(board, nr, nf) == attacker_color + 'N':
                return True

    # Check king attacks (kings can't be adjacent)
    for dr in [-1, 0, 1]:
        for df in [-1, 0, 1]:
            if dr == 0 and df == 0:
                continue
            nr, nf = rank + dr, file + df
            if 0 <= nr < 8 and 0 <= nf < 8:
                if get_piece_at(board, nr, nf) == attacker_color + 'K':
                    return True

    # Check diagonal attacks (bishop, queen)
    for dr, df in [(-1,-1), (-1,1), (1,-1), (1,1)]:
        for i in range(1, 8):
            nr, nf = rank + dr*i, file + df*i
            if not (0 <= nr < 8 and 0 <= nf < 8):
                break
            piece = get_piece_at(board, nr, nf)
            if piece:
                if piece[0] == attacker_color and piece[1] in ['B', 'Q']:
                    return True
                break

    # Check straight attacks (rook, queen)
    for dr, df in [(-1,0), (1,0), (0,-1), (0,1)]:
        for i in range(1, 8):
            nr, nf = rank + dr*i, file + df*i
            if not (0 <= nr < 8 and 0 <= nf < 8):
                break
            piece = get_piece_at(board, nr, nf)
            if piece:
                if piece[0] == attacker_color and piece[1] in ['R', 'Q']:
                    return True
                break

    return False

