        elif piece_type == 'B':
            pos_bonus = BISHOP_TABLE[rank][file] if piece_color == 'w' else BISHOP_TABLE[7-rank][file]
        elif piece_type == 'R':
            pos_bonus = ROOK_TABLE[rank][file] if piece_color == 'w' else ROOK_TABLE[7-rank][file]
        elif piece_type == 'Q':
