                new_board[to_sq] = piece[0] + move[4].upper()

            eval_score = minimax(new_board, color, depth - 1, alpha, beta, False)
            max_eval = max(max_eval, eval_score)
            alpha = max(alpha, eval_score)
            if beta <= alpha:
